        out=d.get('output',{})
        print('---',i,'exit',out.get('exit_code'))
        print('STDOUT:',(out.get('stdout') or '')[:900])
    if d.get('type')=='AssistantMessage':
        for ri in d.get('response_items',[]):
            it=ri.get('item',{})
            if it.get('type')=='function_call':
                print('=== CALL',i,it.get('name'),str(it.get('arguments'))[:400])
